// One Slack message listing new Trustpilot reviews at or under maxStars, grouped by company. Nothing to report: no message.
const max = Number($('Settings').first().json.maxStars ?? 3);
const reviews = $input.all().map((i) => i.json).filter((r) => r.found !== false && r.rating !== null && r.rating !== undefined && r.rating <= max);
if (reviews.length === 0) return [];
const byCompany = {};
for (const r of reviews) (byCompany[r.companyName ?? r.input] ??= []).push(r);
const stars = (n) => '★'.repeat(n) + '☆'.repeat(5 - n);
const blocks = Object.entries(byCompany).map(([company, list]) => {
  const lines = list.slice(0, 10).map((r) => `• ${stars(r.rating)} *${(r.title ?? '').slice(0, 80)}* ${(r.text ?? '(no text)').slice(0, 200)} (${(r.publishedAt ?? '').slice(0, 10)})${r.reviewUrl ? ` <${r.reviewUrl}|open>` : ''}`);
  if (list.length > 10) lines.push(`…and ${list.length - 10} more`);
  return `*${company}*: ${list.length} new review${list.length > 1 ? 's' : ''} at ${max} stars or less\n${lines.join('\n')}`;
});
return [{ json: { text: `:rotating_light: *New Trustpilot reviews to answer*\n\n${blocks.join('\n\n')}`, newReviews: reviews.length } }];
